static void dm_drm_plane_reset ( struct drm_plane * plane ) { struct dm_plane_state * amdgpu_state = NULL ; if ( plane -> state ) { plane -> funcs -> atomic_destroy_state ( plane , plane -> state ) ; } WARN_ON ( amdgpu_state == NULL ) ; if ( amdgpu_state ) { __drm_atomic_helper_plane_reset ( plane , & amdgpu_state -> base ) ; } if ( amdgpu_state ) { amdgpu_state -> sdr_boost = DEFAULT_SDR_BOOST ; } } 